INSERT INTO media_samples (_id, type, file_path, name, duration, thumbnail, aspect_ratio, quality, model, style, prompt, is_playground_generated, collected_at, created_at) VALUES ('69cfccef51ca3d71e44b7c39', 'image', 'my/6720f7a39c5d83f364ab39c9/69cfcced51ca3d71e44b7b19.jpg', 'Prompt: Horizontal 3-panel e-c...', NULL, 'my/6720f7a39c5d83f364ab39c9/69cfcced51ca3d71e44b7b19_thumb.jpg', '4:7', NULL, 'runware-z-image-turbo', 'none', 'Prompt: Horizontal 3-panel e-commerce storyboard for a serum launch: Panel 1, the Urban Muse in morning light, examining tired skin in a vanity mirror—platinum hair in a messy bun, blue-green eyes shadowed, faint freckles under dull tone; Panel 2, her applying the dewy serum with precise dabs, lips pursed in focus, product bottle centered with droplet effects; Panel 3, post-glow reveal: radiant complexion, waves cascading freely, confident gaze direct to camera, freckles popping like stars. Uniform lighting from cool to warm, clean product close-ups with "Hydrate & Shine - $45" tags, hyper-detailed skin textures evolving naturally, 8K photoreal, website-ready with swipe indicators.
INSERT INTO media_samples (_id, type, file_path, name, duration, thumbnail, aspect_ratio, quality, model, style, prompt, is_playground_generated, collected_at, created_at) VALUES ('69cfccd31dc946153a85e7f3', 'image', 'my/6720f7a39c5d83f364ab39c9/69cfcccf1dc946153a85e6fa.jpg', 'Glow in the Dark Forest: An en...', NULL, 'my/6720f7a39c5d83f364ab39c9/69cfcccf1dc946153a85e6fa_thumb.jpg', '1:1', NULL, 'runware-z-image-turbo', 'none', 'Glow in the Dark Forest: An enchanted woodland where trees exhale neon spores that ignite the air in cascading auroras of cyan and magenta. Deer with crystalline antlers graze on luminous moss, their eyes reflecting fractal patterns of forgotten constellations. A lone wanderer in a hooded cloak follows a path of floating lanterns, casting elongated shadows that dance like specters. Overhead canopy filters moonlight into prismatic shards, hyper-detailed bioluminescence, in the vein of James Gurney and Alphonse Mucha, cinematic composition, depth of field, 8K.
INSERT INTO media_samples (_id, type, file_path, name, duration, thumbnail, aspect_ratio, quality, model, style, prompt, is_playground_generated, collected_at, created_at) VALUES ('69cfcca6656e301602a297a2', 'image', 'my/6720f7a39c5d83f364ab39c9/69cfcc98656e301602a29699.jpg', 'A 1930s jazz chanteuse in a fe...', NULL, 'my/6720f7a39c5d83f364ab39c9/69cfcc98656e301602a29699_thumb.jpg', '7:4', NULL, 'runware-z-image-turbo', 'none', 'A 1930s jazz chanteuse in a fedora and fur-collared coat, silhouetted against rain-lashed cafe windows in a fog-shrouded Paris alley; cigarette smoke curls from gloved fingers, her profile etched in high-key slashes of sodium light amid inky puddles, gramophone horns spilling muted brass notes. Stark monochrome with grainy emulsion, dramatic key light carving hollows in her cheekbones, Z-Image noir immersion, vintage Kodak Tri-X stock.
INSERT INTO media_samples (_id, type, file_path, name, duration, thumbnail, aspect_ratio, quality, model, style, prompt, is_playground_generated, collected_at, created_at) VALUES ('69cfcbae8dab45e4d84371b0', 'image', 'my/6720f7a39c5d83f364ab39c9/69cfcbac8dab45e4d8437199.jpg', 'A classic comic book page from...', NULL, 'my/6720f7a39c5d83f364ab39c9/69cfcbac8dab45e4d8437199_thumb.jpg', '4:7', NULL, 'runware-z-image-turbo', 'none', 'A classic comic book page from the 50s, basic drawings, thick lines, moire defects and offset color registry. Panel 1 (top, across the page, establishing shot. View from behind, Superman on the top of a mountain, at his side, Pikachu, both looking at the distance, on the sea a volcano island erupts. Panel 2 (below Panel 1, left side, close up of Superman face, worried, a speech balloon says ''This is a job for''. Panel 3 (below Panel 1, right side, close up of Pikachu in a dynamic pose, surrounded by electric streaks, a speech balloon with spikes say ''PIKACHU!''. Panel 4 (occupying the rest of the page, dynamic shot, Superman and Pikachu flying towards the volcano island, with speed trails behind them).
