INSERT INTO media_samples (_id, type, file_path, name, duration, thumbnail, aspect_ratio, quality, model, style, prompt, is_playground_generated, collected_at, created_at) VALUES ('69cfcb4a656e301602a22748', 'image', 'my/6720f7a39c5d83f364ab39c9/69cfcb48656e301602a226e6.jpg', 'A seamless diptych scene: left...', NULL, 'my/6720f7a39c5d83f364ab39c9/69cfcb48656e301602a226e6_thumb.jpg', '1:1', NULL, 'runware-z-image-turbo', 'none', 'A seamless diptych scene: left side, a bustling Victorian marketplace alive with horse-drawn carriages, cobblestone slick from morning mist, vendors hawking spiced loaves under gas lamps; right side, a pristine alpine meadow at dawn, wildflowers nodding in crisp air, a lone shepherd piping a melody to grazing sheep. The central seam is razor-sharp, with mist tendrils bridging the gap like a dream''s edge. Rich volumetric contrast, hyper-detailed fabrics and petals, Z-Image Turbo fidelity, 8K cinematic split. 
